  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var main = root.querySelector('.u010-main');
  var labs = root.querySelector('.u010-labs');
  var caret = root.querySelector('.u010-caret');
  var live = root.querySelector('.u010-live');
  var opts = Array.prototype.slice.call(root.querySelectorAll('.u010-opt'));
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var cur = opts[0];
  var timers = [];
  function later(fn, ms) { timers.push(setTimeout(function () { if (root.isConnected) fn(); }, ms)); }

  // 문구가 위로 빠지고 새 문구가 아래에서 굴러 들어옵니다
  function roll(text) {
    var old = labs.lastElementChild;
    if (old.textContent === text) return;
    var s = document.createElement('span');
    s.textContent = text;
    s.style.position = 'absolute'; s.style.left = '0'; s.style.top = '0';
    s.style.transform = 'translateY(100%)'; s.style.opacity = '0';
    labs.appendChild(s);
    void s.offsetWidth;
    s.style.transform = 'none'; s.style.opacity = '1';
    old.style.transform = 'translateY(-100%)'; old.style.opacity = '0';
    setTimeout(function () { old.remove(); s.style.position = ''; }, rm ? 0 : 520);
  }
  function setOpen(v, focusFirst) {
    root.dataset.open = v ? '1' : '0';
    caret.setAttribute('aria-expanded', String(v));
    opts.forEach(function (o) { o.tabIndex = v ? 0 : -1; });
    if (v && focusFirst) setTimeout(function () { cur.focus({ preventScroll: true }); }, 30);
  }
  setOpen(false);
  caret.addEventListener('click', function () { setOpen(root.dataset.open !== '1', true); });
  opts.forEach(function (o, i) {
    o.addEventListener('click', function () {
      cur = o;
      opts.forEach(function (x) { x.setAttribute('aria-checked', String(x === o)); });
      roll(o.dataset.mode);
      setOpen(false);
      caret.focus({ preventScroll: true });
    });
    o.addEventListener('keydown', function (e) {
      var d = e.key === 'ArrowDown' ? 1 : e.key === 'ArrowUp' ? -1 : 0;
      if (d) { e.preventDefault(); opts[(i + d + opts.length) % opts.length].focus(); }
    });
  });
  root.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && root.dataset.open === '1') { e.preventDefault(); setOpen(false); caret.focus({ preventScroll: true }); }
  });
  document.addEventListener('pointerdown', function (e) {
    if (root.dataset.open === '1' && root.isConnected && !root.contains(e.target)) setOpen(false);
  });

  // 실행: 진행 막대 → 완료(초록) → 원래 문구로 복귀
  main.addEventListener('click', function () {
    if (root.dataset.state !== 'idle') return;
    setOpen(false);
    root.dataset.state = 'busy';
    roll(cur.dataset.busy);
    live.textContent = cur.dataset.busy;
    later(function () { root.dataset.state = 'done'; roll(cur.dataset.done); live.textContent = cur.dataset.done; }, rm ? 100 : 1600);
    later(function () { root.dataset.state = 'idle'; roll(cur.dataset.mode); live.textContent = ''; }, rm ? 800 : 3400);
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var fab = root.querySelector('.u011-fab');
  var items = Array.prototype.slice.call(root.querySelectorAll('.u011-it'));
  var note = root.querySelector('.u011-note');
  var noteT = root.querySelector('.u011-note span');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var t = 0;
  function setOpen(v) {
    root.classList.toggle('is-open', v);
    fab.setAttribute('aria-expanded', String(v));
    fab.setAttribute('aria-label', v ? '메뉴 닫기' : '새로 만들기');
    items.forEach(function (it) { it.tabIndex = v ? 0 : -1; });
    if (v) note.classList.remove('is-on');
  }
  setOpen(false);
  fab.addEventListener('click', function () { setOpen(!root.classList.contains('is-open')); });
  items.forEach(function (it, i) {
    it.addEventListener('click', function () {
      it.classList.remove('is-picked'); void it.offsetWidth; it.classList.add('is-picked');
      clearTimeout(t);
      t = setTimeout(function () {
        if (!root.isConnected) return;
        setOpen(false);
        noteT.textContent = it.dataset.done;
        note.classList.add('is-on');
        fab.focus({ preventScroll: true });
        t = setTimeout(function () { if (root.isConnected) note.classList.remove('is-on'); }, 1800);
      }, rm ? 0 : 260);
    });
    it.addEventListener('keydown', function (e) {
      var d = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
      if (d) { e.preventDefault(); items[(i + d + items.length) % items.length].focus(); }
    });
  });
  root.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && root.classList.contains('is-open')) { e.preventDefault(); setOpen(false); fab.focus(); }
  });
  document.addEventListener('pointerdown', function (e) {
    if (root.isConnected && root.classList.contains('is-open') && !root.contains(e.target)) setOpen(false);
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u012-btn');
  var num = root.querySelector('.u012-num');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var gid = 'u012-g-' + Math.random().toString(36).slice(2, 7);
  root.querySelector('linearGradient').id = gid;
  root.querySelector('.u012-in').style.fill = 'url(#' + gid + ')';
  var n = 128, t = 0;
  var roll = root.querySelector('.u012-roll');
  // 문구 길이가 달라도 점과 숫자가 자연스럽게 따라오도록 폭을 함께 옮깁니다
  function fitRoll(on) { roll.style.width = roll.children[on ? 1 : 0].offsetWidth + 'px'; }
  fitRoll(false);
  btn.addEventListener('click', function () {
    var on = !root.classList.contains('is-on');
    root.classList.toggle('is-on', on);
    btn.setAttribute('aria-pressed', String(on));
    btn.setAttribute('aria-label', on ? '저장 해제' : '이 글 저장');
    n += on ? 1 : -1;
    num.textContent = n;
    fitRoll(on);
    // 저장할 때만 조각이 흩어집니다
    root.classList.remove('is-burst');
    clearTimeout(t);
    if (on && !rm) {
      void root.offsetWidth;
      root.classList.add('is-burst');
      t = setTimeout(function () { root.classList.remove('is-burst'); }, 900);
    }
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var sw = root.querySelector('.u013-sw');
  var knob = root.querySelector('.u013-knob');
  var lab = root.querySelector('.u013-lab');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var id = 'u013-l-' + Math.random().toString(36).slice(2, 7);
  lab.id = id;
  sw.setAttribute('aria-labelledby', id);
  var on = false, t = 0;

  function set(v) {
    on = v;
    root.classList.toggle('is-on', v);
    sw.setAttribute('aria-checked', String(v));
    // 이동하는 처음 순간에 늘어나고, 도착하면서 원래 폭으로 튕깁니다
    if (!rm) {
      root.classList.add('is-stretch');
      clearTimeout(t);
      t = setTimeout(function () { root.classList.remove('is-stretch'); }, 170);
    }
  }
  // 손잡이를 끌면 따라오고, 놓은 위치가 절반을 넘으면 그쪽으로 붙습니다
  var drag = null;
  sw.addEventListener('pointerdown', function (e) {
    if (e.button !== 0) return;
    drag = { x: e.clientX, moved: false, start: on ? 72 : 8 };
    sw.setPointerCapture(e.pointerId);
  });
  sw.addEventListener('pointermove', function (e) {
    if (!drag) return;
    var k = sw.getBoundingClientRect().width / sw.offsetWidth || 1;
    var dx = (e.clientX - drag.x) / k;
    if (Math.abs(dx) > 4) drag.moved = true;
    if (!drag.moved) return;
    root.classList.add('is-drag');
    var x = Math.max(8, Math.min(72, drag.start + dx));
    knob.style.left = x + 'px';
    knob.style.width = (60 + Math.min(18, Math.abs(dx) * 0.25)) + 'px';
  });
  function end(e) {
    if (!drag) return;
    var d = drag; drag = null;
    root.classList.remove('is-drag');
    var x = parseFloat(knob.style.left || (on ? 72 : 8));
    knob.style.left = ''; knob.style.width = '';
    if (d.moved) { set(x > 40); sw._skip = true; }
  }
  sw.addEventListener('pointerup', end);
  sw.addEventListener('pointercancel', end);
  sw.addEventListener('click', function () {
    if (sw._skip) { sw._skip = false; return; }
    set(!on);
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var ins = Array.prototype.slice.call(root.querySelectorAll('.u014-in'));
  var num = root.querySelector('.u014-num');
  // 체크한 개수에 맞춰 진행 고리와 숫자를 바꾸고, 모두 끝나면 완료 표시로 바꿉니다
  function update() {
    var n = ins.filter(function (i) { return i.checked; }).length;
    root.style.setProperty('--p', (n / ins.length).toFixed(3));
    num.textContent = n + '/' + ins.length;
    root.classList.toggle('is-all', n === ins.length);
  }
  ins.forEach(function (i) { i.addEventListener('change', update); });
  update();
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var opts = Array.prototype.slice.call(root.querySelectorAll('.u015-opt'));
  var frame = root.querySelector('.u015-frame');
  var sel = root.querySelector('.u015-sel');
  var sum = root.querySelector('.u015-sum');
  // 고른 카드 위치로 액자를 옮깁니다. 크기는 레이아웃 값(offset)으로 재서 배율과 무관합니다
  function place(o) {
    frame.style.top = o.offsetTop + 'px';
    frame.style.height = o.offsetHeight + 'px';
  }
  function choose(o, focus) {
    opts.forEach(function (x) {
      var on = x === o;
      x.setAttribute('aria-checked', String(on));
      x.tabIndex = on ? 0 : -1;
    });
    place(o);
    var name = o.querySelector('.u015-txt b').firstChild.textContent.trim();
    var p = +o.dataset.p;
    sel.textContent = name + ' 요금제';
    sum.textContent = p ? '월 ' + p.toLocaleString('ko-KR') + '원' : '무료';
    if (focus) o.focus();
  }
  opts.forEach(function (o, i) {
    o.addEventListener('click', function () { choose(o); });
    o.addEventListener('keydown', function (e) {
      var d = (e.key === 'ArrowDown' || e.key === 'ArrowRight') ? 1 : (e.key === 'ArrowUp' || e.key === 'ArrowLeft') ? -1 : 0;
      if (d) { e.preventDefault(); choose(opts[(i + d + opts.length) % opts.length], true); }
    });
  });
  frame.style.transition = 'none';
  choose(opts[1]);
  requestAnimationFrame(function () { requestAnimationFrame(function () { frame.style.transition = ''; }); });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var wrap = root.querySelector('.u016-stars');
  var score = root.querySelector('.u016-score');
  var word = root.querySelector('.u016-word');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var gid = 'u016-g-' + Math.random().toString(36).slice(2, 7);
  root.querySelector('linearGradient').id = gid;
  var WORDS = ['별을 눌러 주세요', '별로예요', '아쉬워요', '괜찮아요', '좋아요', '최고예요'];
  var COLORS = ['var(--ux-ink-3)', '#E5484D', '#F07A3E', '#E8A317', '#2FB37A', '#7B61FF'];
  var STAR = 'M26 4.5l6.4 13.2 14.4 2-10.5 10.1 2.6 14.3L26 37.3l-12.9 6.8 2.6-14.3L5.2 19.7l14.4-2z';
  var stars = [];
  for (var i = 0; i < 5; i++) {
    var b = document.createElement('span');
    b.className = 'u016-s';
    var sparks = '';
    for (var k = 0; k < 5; k++) sparks += '<i style="--a:' + (k * 72) + 'deg"></i>';
    b.innerHTML = '<svg viewBox="0 0 52 52"><path class="bg" d="' + STAR + '" stroke-linejoin="round"/><path class="fg" d="' + STAR + '" style="fill:url(#' + gid + ')"/></svg>' + sparks;
    b.dataset.v = i + 1;
    wrap.appendChild(b);
    stars.push(b);
  }
  var val = 0;
  function preview(n) { stars.forEach(function (s, i) { s.classList.toggle('is-pre', i < n && i >= val); }); }
  function setWord(n) {
    var old = word.lastElementChild;
    var s = document.createElement('span');
    s.textContent = WORDS[n];
    s.style.color = COLORS[n];
    s.style.transform = 'translateY(100%)'; s.style.opacity = '0';
    word.appendChild(s);
    void s.offsetWidth;
    s.style.transform = 'none'; s.style.opacity = '1';
    old.style.transform = 'translateY(-100%)'; old.style.opacity = '0';
    setTimeout(function () { old.remove(); }, 500);
  }
  // 점수를 정하면 왼쪽부터 차례로 별이 튀어 오릅니다
  function set(n) {
    if (n === val) return;
    var prev = val;
    val = n;
    stars.forEach(function (s, i) {
      var on = i < n;
      s.classList.remove('is-pre');
      if (on && i >= prev) {
        setTimeout(function () {
          if (!root.isConnected) return;
          s.classList.add('is-on');
          if (!rm) { s.classList.remove('is-pop'); void s.offsetWidth; s.classList.add('is-pop'); }
        }, rm ? 0 : (i - prev) * 70);
      } else if (!on) s.classList.remove('is-on', 'is-pop');
    });
    score.textContent = n.toFixed(1);
    score.style.color = n ? COLORS[n] : '';
    setWord(n);
    wrap.setAttribute('aria-valuenow', String(n));
    wrap.setAttribute('aria-valuetext', n ? n + '점, ' + WORDS[n] : '평가 안 함');
  }
  stars.forEach(function (s) {
    s.addEventListener('pointerenter', function () { preview(+s.dataset.v); });
    s.addEventListener('click', function () { set(+s.dataset.v); });
  });
  wrap.addEventListener('pointerleave', function () { preview(0); });
  wrap.addEventListener('keydown', function (e) {
    var d = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 }[e.key];
    if (e.key === 'Home') { e.preventDefault(); set(0); }
    if (e.key === 'End') { e.preventDefault(); set(5); }
    if (d) { e.preventDefault(); set(Math.max(0, Math.min(5, val + d))); }
    if (/^[0-5]$/.test(e.key)) set(+e.key);
  });
})();
